import 'dotenv/config';
import path from 'path';
import { promisify } from 'util';

import * as grpc from '@grpc/grpc-js';
import * as protoLoader from '@grpc/proto-loader';
import { grpcServer } from '@src/services/grpc';

const CORE_PROTO_PATH = path.join(__dirname, '../../../../proto/ethereum/ethereum.core.proto');
const GNOSIS_PROTO_PATH = path.join(__dirname, '../../../../proto/ethereum/ethereum.gnosis.proto');

const corePackageDefinition = protoLoader.loadSync(CORE_PROTO_PATH, {
  longs: String,
  defaults: false,
  oneofs: true,
});
const CoreEthereum = (grpc.loadPackageDefinition(corePackageDefinition) as any)?.ethereum.core.Ethereum;

const GnosisPackageDefinition = protoLoader.loadSync(GNOSIS_PROTO_PATH, {
  longs: String,
  defaults: false,
  oneofs: true,
});
const GnosisEthereum = (grpc.loadPackageDefinition(GnosisPackageDefinition) as any)?.ethereum.gnosis.Ethereum;

let coreClient;
let gnosisClient;

describe('Ethereum Gnosis service', () => {
  describe('GRPC service', () => {
    beforeAll(async () => {
      await grpcServer.start();
      coreClient = new CoreEthereum(`localhost:${process.env.GRPC_PORT}`, grpc.credentials.createInsecure());
      gnosisClient = new GnosisEthereum(`localhost:${process.env.GRPC_PORT}`, grpc.credentials.createInsecure());
    });

    afterAll(async () => {
      coreClient?.close();
      gnosisClient?.close();
      await grpcServer.stop();
    });

    describe('eip1559 transaction', () => {
      describe('GetAccountAddress', () => {
        test('generate 2 of 3 multi address', async () => {
          const Method = promisify(gnosisClient.GetAccountAddress.bind(gnosisClient));
          const response = await Method({
            threshold: 2,
            keys: [
              '02f4147da97162a214dbe25828ee4c4acc4dc721cd0c15b2761b43ed0292ed82b5',
              '0377155e520059d3b85c6afc5c617b7eb519afadd0360f1ef03aff3f7e3f5438dd',
              '02f44bce3eecd274e7aa24ec975388d12905dfc670a99b16e1d968e6ab5f69b266',
            ],
            sender: '0xd73d9aa55abbd6cfbed3e9ad7f8be2f6d83c70dc',
            network: {
              chainId: 4,
              hardFork: 'london',
              provider: 'https://rinkeby.infura.io/v3/de9290b603fc4609a6f0a65e23e8c7d3',
            },
            saltNonce: 1644659321895,
          });
          const { address, saltNonce } = response;
          expect(saltNonce).toStrictEqual('1644659321895');
          expect(address).toStrictEqual('0xEcf70be9a60379BBA4344900Ce5C91E31e6AC6fc');
        });
      });

      describe('BuildAccountTransaction', () => {
        test('generate 2 of 3 multi address', async () => {
          const Method = promisify(gnosisClient.BuildAccountTransaction.bind(gnosisClient));
          const response = await Method({
            threshold: 2,
            keys: [
              '02f4147da97162a214dbe25828ee4c4acc4dc721cd0c15b2761b43ed0292ed82b5',
              '0377155e520059d3b85c6afc5c617b7eb519afadd0360f1ef03aff3f7e3f5438dd',
              '02f44bce3eecd274e7aa24ec975388d12905dfc670a99b16e1d968e6ab5f69b266',
            ],
            sender: '0xd73d9aa55abbd6cfbed3e9ad7f8be2f6d83c70dc',
            network: {
              chainId: 4,
              hardFork: 'london',
              provider: 'https://rinkeby.infura.io/v3/de9290b603fc4609a6f0a65e23e8c7d3',
            },
            saltNonce: 1644659321895,
            params: {
              type: 2,
              nonce: 9,
              gasLimit: '0x4baf3',
              maxFeePerGas: '0x4190ab07',
              maxPriorityFeePerGas: '0x4190aaf3',
            },
          });
          const { serialized, signatures, address, estimatedFee } = response;
          expect(estimatedFee).toBeDefined();
          expect(serialized).toStrictEqual(
            '',
          );
          expect(address).toStrictEqual('0xEcf70be9a60379BBA4344900Ce5C91E31e6AC6fc');
          expect(signatures).toEqual(
            expect.arrayContaining([
              expect.objectContaining({
                hash: '19f2764775aa8a859b228318a0d3afd6c75613c8e4d3c4276026ba33b1a72246',
              }),
            ]),
          );
        });

        test('sign tx', async () => {
          const Method = promisify(coreClient.SignTransaction.bind(coreClient));
          const response = await Method({
            serialized:
              '',
            signatures: [
              {
                signature:
                  '65c726ff6f49974e1b5cb77bee9184e23286eae0a000f01cc5163238695ed3ea30daa960aaf49e661829ff8a4921cd267955109ab9bafc6158da6aa7d24de04401',
                hash: '19f2764775aa8a859b228318a0d3afd6c75613c8e4d3c4276026ba33b1a72246',
              },
            ],
            network: {
              provider: 'https://rinkeby.infura.io/v3/de9290b603fc4609a6f0a65e23e8c7d3',
              chainId: 4,
              hardFork: 'london',
            },
          });
          const { serialized, hash, estimatedFee } = response;
          expect(estimatedFee).toBeDefined();
          expect(serialized).toStrictEqual(
            '',
          );
          expect(hash).toStrictEqual('0x9875373744cbc77820458091f57d67e2673436f0edca7312353e6c5058b3fefc');
        });
      });

      describe('ETH TX, txid 0xe0ff6cb34bb1bf30e80acaf3bedd0dd19a108f9066a24fadbee5564973f2467a', () => {
        describe('build input -> sign input -> build tx -> sign tx', () => {
          test('build multisig transfer input', async () => {
            const Method = promisify(gnosisClient.BuildMultisigTransferInput.bind(gnosisClient));
            const response = await Method({
              network: {
                chainId: 4,
                provider: 'https://rinkeby.infura.io/v3/eb95583755214676866b88506b0c25fe',
              },
              quantity: '10000000000000000',
              toAddress: '0x0d5a689d6a973e945cbbfab37202a1788e5588e7',
              contract: '0xd7609c88EE60Ec0b2f72234380311dD5f34273FA',
              contractNonce: 6,
              participants: ['0238127912fd34ff09b7e1733384b1b4953a0e841e89af2405c285204a00044997'],
              sender: '0x0d5a689d6a973e945cbbfab37202a1788e5588e7',
            });

            expect(response).toHaveProperty(
              'serialized',
              '',
            );

            expect(response.signatures).toEqual(
              expect.arrayContaining([
                expect.objectContaining({
                  pubKey: '0238127912fd34ff09b7e1733384b1b4953a0e841e89af2405c285204a00044997',
                  hash: 'b28864d312e37477f0938ca92c5a80010c767a646f113c718fb94fd310c3d249',
                }),
              ]),
            );
          });

          test('sign multisig transfer input', async () => {
            const Method = promisify(gnosisClient.SignMultisigTransferInput.bind(gnosisClient));
            const response = await Method({
              serialized:
                '',
              signatures: [
                {
                  pubKey: '0238127912fd34ff09b7e1733384b1b4953a0e841e89af2405c285204a00044997',
                  hash: 'b28864d312e37477f0938ca92c5a80010c767a646f113c718fb94fd310c3d249',
                  signature:
                    'eb211327feaa6301aa0470a6ef41b75b76261f95ae5be63f982e7bf1c1b43f1049f9b8ee7b347d519b55a2dc0def7917b1f58a7299debfd6134e51829a81eb8300',
                },
              ],
            });

            expect(response).toHaveProperty(
              'serialized',
              '',
            );
          });

          test('build multisig transfer transaction with input', async () => {
            const Method = promisify(gnosisClient.BuildMultisigTransferTransaction.bind(gnosisClient));
            const response = await Method({
              data: '',
              contract: '0xd7609c88ee60ec0b2f72234380311dd5f34273fa',
              sender: '0x0d5a689d6a973e945cbbfab37202a1788e5588e7',
              params: {
                nonce: 73,
                type: 2,
                maxFeePerGas: '0x3b9c50ac',
                maxPriorityFeePerGas: '0x3b9aca00',
                gasLimit: '0xebf1',
              },
              network: {
                chainId: 4,
                hardFork: 'london',
                provider: 'https://rinkeby.infura.io/v3/de9290b603fc4609a6f0a65e23e8c7d3',
              },
            });

            expect(response).toHaveProperty(
              'serialized',
              '',
            );

            expect(response.signatures).toEqual(
              expect.arrayContaining([
                expect.objectContaining({
                  hash: '455325cc75e9993418b715d177cbf2b635cc25a1f66cf50aa5c5d884d4bffb1a',
                }),
              ]),
            );
          });

          test('build multisig transfer transaction with signature', async () => {
            const Method = promisify(gnosisClient.BuildMultisigTransferTransaction.bind(gnosisClient));
            const response = await Method({
              serialized:
                '',
              signatures: [
                {
                  pubKey: '0238127912fd34ff09b7e1733384b1b4953a0e841e89af2405c285204a00044997',
                  hash: 'b28864d312e37477f0938ca92c5a80010c767a646f113c718fb94fd310c3d249',
                  signature:
                    'eb211327feaa6301aa0470a6ef41b75b76261f95ae5be63f982e7bf1c1b43f1049f9b8ee7b347d519b55a2dc0def7917b1f58a7299debfd6134e51829a81eb8300',
                },
              ],
              contract: '0xd7609c88ee60ec0b2f72234380311dd5f34273fa',
              sender: '0x0d5a689d6a973e945cbbfab37202a1788e5588e7',
              params: {
                nonce: 73,
                type: 2,
                maxFeePerGas: '0x3b9c50ac',
                maxPriorityFeePerGas: '0x3b9aca00',
                gasLimit: '0xebf1',
              },
              network: {
                chainId: 4,
                hardFork: 'london',
                provider: 'https://rinkeby.infura.io/v3/de9290b603fc4609a6f0a65e23e8c7d3',
              },
            });

            expect(response).toHaveProperty(
              'serialized',
              '',
            );

            expect(response.signatures).toEqual(
              expect.arrayContaining([
                expect.objectContaining({
                  hash: '455325cc75e9993418b715d177cbf2b635cc25a1f66cf50aa5c5d884d4bffb1a',
                }),
              ]),
            );
          });

          test('sign tx', async () => {
            const Method = promisify(coreClient.SignTransaction.bind(coreClient));
            const response = await Method({
              serialized:
                '',
              signatures: [
                {
                  signature:
                    '96b25c8871ff2c405121f85dec13056ffe8a5f35a71e1724cef5dd3746c0c03946551908c6c7c67112e4de4093852c5d78a5630e4da0c59b735fc90907631b1401',
                  hash: '455325cc75e9993418b715d177cbf2b635cc25a1f66cf50aa5c5d884d4bffb1a',
                },
              ],
              network: {
                provider: 'https://rinkeby.infura.io/v3/de9290b603fc4609a6f0a65e23e8c7d3',
                chainId: 4,
                hardFork: 'london',
              },
            });
            const { serialized, hash, estimatedFee } = response;
            expect(estimatedFee).toBeDefined();
            expect(serialized).toStrictEqual(
              '',
            );
            expect(hash).toStrictEqual('0xe0ff6cb34bb1bf30e80acaf3bedd0dd19a108f9066a24fadbee5564973f2467a');
          });
        });
      });

      describe('ETC20 TX', () => {
        test('build erc20 multisig transfer input', async () => {
          const Method = promisify(gnosisClient.BuildMultisigERC20TransferInput.bind(gnosisClient));
          const response = await Method({
            network: {
              chainId: 4,
              provider: 'https://rinkeby.infura.io/v3/eb95583755214676866b88506b0c25fe',
            },
            tokenAddress: '0x01BE23585060835E02B77ef475b0Cc51aA1e0709',
            toAddress: '0x0d5a689d6a973e945cbbfab37202a1788e5588e7',
            quantity: '10000000000000000',
            contract: '0xd7609c88EE60Ec0b2f72234380311dD5f34273FA',
            contractNonce: 7,
            sender: '0d5a689d6a973e945cbbfab37202a1788e5588e7',
            participants: ['0238127912fd34ff09b7e1733384b1b4953a0e841e89af2405c285204a00044997'],
          });

          expect(response).toHaveProperty(
            'serialized',
            '',
          );

          expect(response.signatures).toEqual(
            expect.arrayContaining([
              expect.objectContaining({
                pubKey: '0238127912fd34ff09b7e1733384b1b4953a0e841e89af2405c285204a00044997',
                hash: 'de5082db906b45b032eb9edcec16764cc5f5637b0b360ef71aed3eb58828ea09',
              }),
            ]),
          );
        });

        test('sign erc20 multisig transfer input', async () => {
          const Method = promisify(gnosisClient.SignMultisigERC20TransferInput.bind(gnosisClient));
          const response = await Method({
            serialized:
              '',
            signatures: [
              {
                pubKey: '0238127912fd34ff09b7e1733384b1b4953a0e841e89af2405c285204a00044997',
                hash: 'de5082db906b45b032eb9edcec16764cc5f5637b0b360ef71aed3eb58828ea09',
                signature:
                  '4e6b3e839ad7125bb1f15f0aca937edc1fae64e141c2f8d3c31ecc409be2ddb45624a7353ac2cb2276bbc0aee52138cd642235896b05aaab22dfbbb44fe5d61c01',
              },
            ],
          });

          expect(response).toHaveProperty(
            'serialized',
            '',
          );
        });
      });
    });
  });
});
